import {createGardenState,stepGarden} from '../../../../src/js/garden/GardenSimulation.js';
import {GARDEN_ART} from '../../../../src/js/garden/GardenArt.js';
import {GARDEN as C,GARDEN_PLATFORM_BY_ID,GARDEN_ENEMIES,GARDEN_WATERS,GARDEN_FINAL_START,gardenPlatforms} from '../../../../src/js/garden/GardenLevel.js';
import {ToyRoomPhase} from '../../../../src/js/toy-room/ToyRoomPhase.js';
const check=(value,label)=>{if(!value)throw Error(label);};
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function prepared(phase){for(let i=0;i<200&&!phase.ready;i++){if(phase.error)throw Error(phase.error);await wait(50);}check(phase.ready,'Artes prontas');}
export async function start(difficulty='NORMAL'){
 const g=review.game;await g.assetsReady;g.startDebugPhase('garden',difficulty);const p=g.state.toyRoomInstance.instance.garden;await prepared(p);g.setPaused(true);p.state.stage='RUNNING';p.state.age=5;return true;
}
export async function audit(){
 const g=review.game,r=g.state.toyRoomInstance.instance,phase=r.garden,renderer=phase.renderer,shots=[];let frames=0;
 for(const [key,set]of Object.entries(GARDEN_ART.sets)){
  const image=renderer.images.get(set.file);check(image,'Imagem carregada');const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0);const data=ctx.getImageData(0,0,canvas.width,canvas.height).data;
  for(const f of set.frames){let opaque=0,transparent=0,bottom=0;for(let y=0;y<f.h;y++)for(let x=0;x<f.w;x++){const a=data[((f.y+y)*canvas.width+f.x+x)*4+3];if(a>128)opaque++;if(!a)transparent++;if(a)bottom=y+1;}check(opaque>100,'Recorte visível');if(key.startsWith('menina')){check(transparent>100,'Alfa real da menina');check(bottom===f.anchorY,'Pés ancorados');}frames++;}
 }
 const unchanged=JSON.stringify(phase.state);phase.render();check(JSON.stringify(phase.state)===unchanged,'Desenho puro');const f=renderer.frame(phase.state);phase.state.player.y-=240;const jump=renderer.frame(phase.state);check(f.scale===jump.scale&&f.oy===jump.oy,'Câmera lateral fixa');
 const locations=[['casa',150],['grama',1750],['pedrinhas',4400],['roda',5050],['nuvens',5650],['lagarta-vermelha',6500],['rio-com-formiga',GARDEN_ENEMIES.find(e=>e.route).x],['paisagem-longa',C.width*.55],['quatro-nuvens',GARDEN_FINAL_START+1050],['piquenique',C.goal]];
 for(const [label,x]of locations){phase.state=createGardenState();phase.state.stage=label==='piquenique'?'COMPLETE':'RUNNING';phase.state.time=12;phase.state.age=4;const support=gardenPlatforms(12,phase.state,x).filter(p=>x>=p.x&&x<=p.x+p.w).sort((a,b)=>a.y-b.y)[0];Object.assign(phase.state.player,{x,y:support?.y??480,onGround:Boolean(support),support:support?.id??null,terrain:support?.type??'cloud',discomfort:['grama','pedrinhas'].includes(label)?1:0});phase.state.fairy.x=x;phase.state.fairy.y=phase.state.player.y-135;if(label==='lagarta-vermelha'){const e=phase.state.enemies.find(e=>e.type==='caterpillar');e.hp=1;e.x=x+110;}phase.render();shots.push({label,data:phase.canvas.toDataURL()});}
 for(const [label,kind]of [['resgate','fall'],['desnorteada','hurt']]){phase.difficulty='EASY';phase.state=createGardenState('EASY');phase.state.stage='RUNNING';phase.state.hp=1;if(kind==='fall')Object.assign(phase.state.player,{x:720,y:900,onGround:false});else{const e=phase.state.enemies.find(e=>e.type==='caterpillar');Object.assign(phase.state.player,{x:e.x,y:e.y,onGround:false});phase.state.trail=['grama-da-margem','pedrinhas-da-roda','primeiros-bichinhos'];}stepGarden(phase.state,{},1/60,'EASY');check(phase.state.stage===('fall'===kind?'RESCUING':'DISORIENTED'),'EASY recupera sem derrota');stepGarden(phase.state,{},.2,'EASY');phase.render();shots.push({label,data:phase.canvas.toDataURL()});check(!g.isGameOver(),'Host não termina EASY');}
 phase.difficulty='NORMAL';phase.state=createGardenState();phase.state.stage='RUNNING';g.setPaused(false);const original=Object.getOwnPropertyDescriptor(navigator,'getGamepads');try{Object.defineProperty(navigator,'getGamepads',{configurable:true,value:()=>[{connected:true,axes:[.8],buttons:Array.from({length:16},(_,i)=>({pressed:i===0}))}]});const pad=phase.input.sample();check(pad.x===.8&&pad.jump,'Gamepad simultâneo');}finally{if(original)Object.defineProperty(navigator,'getGamepads',original);else delete navigator.getGamepads;}
 const frozen=JSON.stringify(phase.state);window.dispatchEvent(new Event('blur'));phase.update(30);check(JSON.stringify(phase.state)===frozen,'Perda de foco congela');window.dispatchEvent(new Event('focus'));check(!phase.paused,'Foco retoma');g.setPaused(true);
 const canvas=document.createElement('canvas');canvas.width=960;canvas.height=540;const room=new ToyRoomPhase(canvas,null,null,null,{assets:g.assets,bindInputs:false});room.story.state.arenaCompleted=true;room.arena.state.completed=true;room.tutorial.finish();let destroyed=0;room.chase={active:true,campaign:true,state:{stage:'COMPLETE'},update(){},destroy(){destroyed++;}};room.update(150);check(room.garden?.active&&destroyed===1,'Campanha descarta fuga e abre jardim');await prepared(room.garden);
 room.garden.state.stage='RUNNING';const ground=GARDEN_PLATFORM_BY_ID.get('trecho-10-caminho');Object.assign(room.garden.state.player,{x:ground.x+100,y:ground.y,support:ground.id});const saved=room.snapshot();check(saved.toyRoomGarden&&!saved.toyRoomChaseCampaign,'Save ativo só do jardim');room.restore(saved);await prepared(room.garden);check(room.garden.state.player.x===ground.x+100,'Save restaura avanço');const before=JSON.stringify(room.garden.snapshot());room.garden.setPaused(true);room.garden.update(60);check(JSON.stringify(room.garden.snapshot())===before,'Pausa congela relógios');room.garden.state.stage='GAME_OVER';check(room.retryDefeat(),'Retry normal pelo host');const p=room.garden;room.destroy();check(!p.input.installed&&p.renderer.images.size===0&&p.audio.voices.size===0,'Descarte integral');
 return{frames,shots,camera:true,transition:true,save:true,pause:true,immortal:true,dispose:true};
}
export function controls(){const phase=review.game.state.toyRoomInstance.instance.garden,canvas=phase.canvas,rect=canvas.getBoundingClientRect();return Object.fromEntries(Object.entries(phase.renderer.controls()).map(([key,b])=>[key,{x:rect.left+b.x/canvas.width*rect.width,y:rect.top+b.y/canvas.height*rect.height}]));}
